<?php
require '../config/auth.php'; wajib_role('guru'); require '../config/database.php';
$per=(int)($_GET['per']??10); if(!in_array($per,[10,15,20,25,50],true))$per=10;
$page=max(1,(int)($_GET['page']??1)); $search=trim($_GET['cari']??''); $like='%'.$conn->real_escape_string($search).'%';
$where="(u.username LIKE '$like' OR u.nama LIKE '$like' OR g.nip LIKE '$like' OR mp.nama_mapel LIKE '$like')";
$total=(int)$conn->query("SELECT COUNT(DISTINCT g.id) n FROM guru g JOIN users u ON u.id=g.user_id LEFT JOIN mapel mp ON mp.guru_id=g.id WHERE $where")->fetch_assoc()['n'];
$pages=max(1,(int)ceil($total/$per)); $page=min($page,$pages); $offset=($page-1)*$per;
$rows=$conn->query("SELECT u.username,u.role,g.nama_lengkap,GROUP_CONCAT(DISTINCT mp.nama_mapel ORDER BY mp.nama_mapel SEPARATOR ', ') mapel FROM guru g JOIN users u ON u.id=g.user_id LEFT JOIN mapel mp ON mp.guru_id=g.id WHERE $where GROUP BY g.id ORDER BY g.nama_lengkap LIMIT $per OFFSET $offset");
function teacherPage($n){$q=$_GET;$q['page']=$n;return '?'.http_build_query($q);}
?>
