<section class="panel"><h2>Daftar Guru</h2><form method="get" class="toolbar"><select name="per"><option value="10" <?=$per===10?'selected':''?>>10</option><option value="15" <?=$per===15?'selected':''?>>15</option><option value="20" <?=$per===20?'selected':''?>>20</option><option value="25" <?=$per===25?'selected':''?>>25</option><option value="50" <?=$per===50?'selected':''?>>50</option></select><input name="cari" value="<?=h($search)?>" placeholder="Cari username, nama, atau mapel..."><button class="btn primary">Cari</button></form><div class="table-wrap"><table><thead><tr><th>No</th><th>Username</th><th>Role</th><th>Nama</th><th>Mapel</th></tr></thead><tbody><?php $i=$offset+1;while($r=$rows->fetch_assoc()):?><tr><td><?=$i++?></td><td><?=h($r['username'])?></td><td><?=h($r['role'])?></td><td><?=h($r['nama_lengkap'])?></td><td><?=h($r['mapel']?:'-')?></td></tr><?php endwhile;?><?php if($total===0):?><tr><td colspan="5">Belum ada data guru.</td></tr><?php endif;?></tbody></table></div><div class="pagination"><span>Menampilkan halaman <?=$page?> dari <?=$pages?> · <?=$total?> data</span><div><?php for($i=1;$i<=$pages;$i++):if($i===1||$i===$pages||abs($i-$page)<=1):?><a class="<?=$i===$page?'current':''?>" href="<?=teacherPage($i)?>"><?=$i?></a><?php elseif(abs($i-$page)===2):?><a href="<?=teacherPage($i)?>">…</a><?php endif;endfor;?></div></div></section>
</main></body></html>
